// === Tab: mySketch.js ===
let particles =[]

function setup() {
	createCanvas(1112, 834);
	pixelDensity(1)
	colorMode(HSB)
	background(20,70,40);
	for (var o=0;o<height+5;o+=8){
		for (var i=0;i<width+5;i+=8){
			particles.push({
				x:i,
				y:o,
				clr:color(25,50,20)
			})
		}
	}
}

function draw() {
	// colorMode(HSB)
	background(25,35,80,0);
	blendMode(ADD)
	noStroke()
	for (i=0;i<particles.length;i++){
		let p = particles[i]
		fill(p.clr)
		ellipse(p.x,p.y,1)
		p.x+=(noise(p.x/1000,p.y/100,10)-0.5)*15
		p.y+=(noise(p.x/100,p.y/1000,1000)-0.5)*15
		//除的數字越大，noise在連續波形上取樣的間隔會越近
		//()*3動快一點
	}
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg"); 
    lapse = millis();
  } 
}

